package dev.zomboid.tacz;
import java.lang.reflect.*;
public final class Weather {
 static long testStart;static int testHold;static int mode; // 0 automatic, 1 test, -1 disabled
 public static int holdSeconds(long interval){long mixed=interval*6364136223846793005L+1442695040888963407L;return 120+(int)Math.floorMod(mixed^(mixed>>>32),481);}
 public static double envelope(double seconds,int hold){if(seconds<0||seconds>=hold+120)return 0;double t=Math.min(1,Math.min(seconds/60,(hold+120-seconds)/60));return t*t*(3-2*t);}
 public static double cycle(long time){long age=time-24000,interval=Math.floorDiv(age,72000);double seconds=Math.floorMod(age,72000)/20d;return envelope(seconds,holdSeconds(interval));}
 static double strength(){if(mode<0)return 0;if(mode==1){double seconds=(System.nanoTime()-testStart)/1e9;if(seconds<testHold+120)return envelope(seconds,testHold);mode=0;}Object level=R.get(Bridge.mc(),"level");return level==null?0:cycle(((Number)R.call(level,"getGameTime")).longValue());}
 public static void fog(Object event){try{double s=strength();if(s<=0||!R.call(event,"getType").toString().equals("NONE")||!R.call(event,"getMode").toString().equals("FOG_TERRAIN"))return;Object camera=R.call(event,"getCamera"),player=R.get(Bridge.mc(),"player");double offset=player==null?0:R.num(R.call(R.call(camera,"getPosition"),"distanceTo",R.call(player,"getEyePosition")));float far=(float)R.num(R.call(event,"getFarPlaneDistance")),near=(float)R.num(R.call(event,"getNearPlaneDistance"));R.call(event,"setFarPlaneDistance",(float)(far+(Math.min(far,offset+12)-far)*s));R.call(event,"setNearPlaneDistance",(float)Math.max(0,near+(Math.min(near,offset+2)-near)*s));R.call(event,"setCanceled",true);}catch(Throwable e){Bridge.warn("periodic atmospheric fog",e);}}
 public static void finalFog(Object camera,Object fogMode){try{double strength=strength();if(strength<=0||!Bridge.isoActive()||!fogMode.toString().equals("FOG_TERRAIN")||!R.call(camera,"getFluidInCamera").toString().equals("NONE"))return;Object render=R.type("com.mojang.blaze3d.systems.RenderSystem"),player=R.get(Bridge.mc(),"player");double offset=player==null?0:R.num(R.call(R.call(camera,"getPosition"),"distanceTo",R.call(player,"getEyePosition"))),near=R.num(R.call(render,"getShaderFogStart")),far=R.num(R.call(render,"getShaderFogEnd"));R.call(render,"setShaderFogStart",(float)(near+(Math.min(near,offset+2)-near)*strength));R.call(render,"setShaderFogEnd",(float)(far+(Math.min(far,offset+12)-far)*strength));}catch(Throwable e){Bridge.warn("isometric atmospheric fog override",e);}}
 public static void color(Object event){try{double s=strength();if(s<=0)return;String[] get={"getRed","getGreen","getBlue"},set={"setRed","setGreen","setBlue"};double[] target={.55,.59,.60};for(int i=0;i<3;i++){double value=R.num(R.call(event,get[i]));R.call(event,set[i],(float)(value+(target[i]-value)*s*.7));}}catch(Throwable e){Bridge.warn("fog color",e);}}
 public static void commands(Object event){try{Object root=R.call(R.type("com.mojang.brigadier.builder.LiteralArgumentBuilder"),"literal","zomboidfog");for(String name:new String[]{"prueba","auto","off"}){Object command=R.call(R.type("com.mojang.brigadier.builder.LiteralArgumentBuilder"),"literal",name);Class<?> api=R.type("com.mojang.brigadier.Command");Object handler=Proxy.newProxyInstance(api.getClassLoader(),new Class<?>[]{api},(proxy,method,args)->{if(method.getName().equals("run")){mode=name.equals("off")?-1:name.equals("prueba")?1:0;testStart=System.nanoTime();testHold=java.util.concurrent.ThreadLocalRandom.current().nextInt(120,601);Object player=R.get(Bridge.mc(),"player");if(player!=null)R.call(player,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"literal","Niebla: "+name+(mode==1?" (entrada 60 s; fuerte "+testHold+" s; salida 60 s)":"")),false);return 1;}if(method.getName().equals("toString"))return "ZomboidFogCommand";if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);return proxy==args[0];});R.call(command,"executes",handler);R.call(root,"then",command);}R.call(R.call(event,"getDispatcher"),"register",root);}catch(Throwable e){Bridge.warn("fog test commands",e);}}
}
